class Plot:
    def __init__(self, data):
        self.data = data
        self.scales = {}

    def scale(self, **kwargs):
        self.scales.update(kwargs)
        return self

    def get_legend_handles(self):
        return {k: f"scale_{v}" for k, v in self.scales.items()}

