import unittest
from seaborn.plot import Plot

class TestPlot(unittest.TestCase):
    def test_scale_legend(self):
        p = Plot([1, 2, 3]).scale(x='log', y='linear')
        self.assertEqual(p.get_legend_handles(), {'x': 'scale_log', 'y': 'scale_linear'})

if __name__ == '__main__': unittest.main()
